/**
 * Official municipal boundaries for every supported city.
 *
 * These JSON files are generated by `bun run boundary:fetch` and committed.
 * This module is server-side only: importing it from a client component would
 * bundle every boundary into the browser.
 */

import cormeilles from "../../data/boundary/cormeilles-en-parisis-95176.v1.json";
import franconville from "../../data/boundary/franconville-95252.v1.json";
import herblay from "../../data/boundary/herblay-sur-seine-95306.v1.json";
import pierrelaye from "../../data/boundary/pierrelaye-95488.v1.json";
import saintLeu from "../../data/boundary/saint-leu-la-foret-95563.v1.json";
import taverny from "../../data/boundary/taverny-95607.v1.json";
import type { BoundaryFeature, BoundaryGeometry } from "./boundary";
import { boundaryBoundingBox } from "./boundary";

function asFeature(value: unknown): BoundaryFeature {
  return value as BoundaryFeature;
}

const HERBLAY = asFeature(herblay);

const BOUNDARIES: Record<string, BoundaryFeature> = {
  "95306": HERBLAY,
  "95563": asFeature(saintLeu),
  "95607": asFeature(taverny),
  "95488": asFeature(pierrelaye),
  "95176": asFeature(cormeilles),
  "95252": asFeature(franconville),
};

export function getCityBoundary(insee: string): BoundaryFeature | null {
  return BOUNDARIES[insee] ?? null;
}

export function getCityBoundaryGeometry(insee: string): BoundaryGeometry | null {
  return getCityBoundary(insee)?.geometry ?? null;
}

export function getCityBoundingBox(insee: string): ReturnType<typeof boundaryBoundingBox> | null {
  const geometry = getCityBoundaryGeometry(insee);
  return geometry ? boundaryBoundingBox(geometry) : null;
}

export const CITY_BOUNDARIES = BOUNDARIES;
